Bytes load(const std::string& path,std::size_t cap){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("input open");auto n=f.tellg();if(n<0||std::uintmax_t(n)>cap)throw std::runtime_error("input capacity");Bytes b(static_cast<std::size_t>(n));f.seekg(0);if(!f.read(reinterpret_cast<char*>(b.data()),static_cast<std::streamsize>(b.size()))||f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("input changed");return b;}
struct Reader{std::span<const std::uint8_t>b;std::size_t p{};std::span<const std::uint8_t>take(std::size_t n){if(n>b.size()-p)throw std::runtime_error("fixture truncated");auto x=b.subspan(p,n);p+=n;return x;}U u(){const auto x=take(4);return U(x[0])|(U(x[1])<<8)|(U(x[2])<<16)|(U(x[3])<<24);}std::string text(){auto n=u();check(n>0&&n<=256,"text capacity");auto x=take(n);return {x.begin(),x.end()};}void end(){check(p==b.size(),"fixture trailing");}};
U word(std::span<const std::uint8_t>b,std::size_t p){check(p<=b.size()&&b.size()-p>=4,"word extent");return U(b[p])|(U(b[p+1])<<8)|(U(b[p+2])<<16)|(U(b[p+3])<<24);}
