sq::Scene scene(const Case&c,const cr::Resource&r){sq::Scene s;for(auto&x:s.direct)x=std::vector<sq::Node>{};for(auto&f:s.other_empty)for(auto&x:f)x=true;for(auto&f:s.extra_c8_empty)for(auto&x:f)x=true;s.extra_c8_enabled=true;s.extra_c9_enabled=true;s.extra_c9_empty=true;s.extra_tail_count=0;s.status_selector_a=0;s.status_selector_b=0;for(unsigned i=0;i<3;++i){s.classification_masks[i]=c.masks[i];s.normal_thresholds[i]=c.thresholds[i];}sq::Instance x;x.enabled_5=static_cast<std::uint8_t>(c.enabled);x.bypass_pair_box_33=0;x.object_mask=1;x.area_mask=8;x.exclusion_tag=0;x.resource_present=true;x.tree_present=false;x.grid_present=true;x.resource=r;x.status_count=1;x.grid_state=0;x.status={1,0,0,false,false};s.instances.push_back(x);const auto&g=r.groups()[0];s.direct[3]=std::vector<sq::Node>{{0,g.bbox_min[0],g.bbox_max[2]}};s.grid_states.push_back({r,0,0,0,std::vector<std::optional<U>>(g.pairs.count,0)});return s;}
template<class T>void append(std::vector<U>&b,const std::optional<T>&x){b.push_back(bool(x));if(x)b.push_back(static_cast<U>(*x));}
std::vector<U> scene_snapshot(const sq::Scene&s){std::vector<U>b;
 for(const auto&g:s.grid_states){for(char c:g.resource.sha256())b.push_back(static_cast<unsigned char>(c));b.push_back(g.group);append(b,g.counter);append(b,g.depth);for(auto x:g.pair_marks)append(b,x);}
 for(const auto&i:s.instances){append(b,i.enabled_5);append(b,i.bypass_pair_box_33);append(b,i.object_mask);append(b,i.area_mask);append(b,i.exclusion_tag);append(b,i.resource_present);append(b,i.tree_present);append(b,i.grid_present);b.push_back(bool(i.resource));if(i.resource)for(char c:i.resource->sha256())b.push_back(static_cast<unsigned char>(c));append(b,i.status_count);append(b,i.grid_state);append(b,i.status.enabled_c);append(b,i.status.disabled_1f);append(b,i.status.field20);append(b,i.status.pointer24_present);append(b,i.status.pointer30_present);}
 for(const auto&d:s.direct){b.push_back(bool(d));if(d){b.push_back(static_cast<U>(d->size()));for(const auto&n:*d){append(b,n.instance);append(b,n.minimum_x);append(b,n.maximum_z);}}}
 for(const auto&family:s.other_empty)for(auto x:family)append(b,x);for(const auto&family:s.extra_c8_empty)for(auto x:family)append(b,x);append(b,s.extra_c8_enabled);append(b,s.extra_c9_enabled);append(b,s.extra_c9_empty);append(b,s.extra_tail_count);append(b,s.status_selector_a);append(b,s.status_selector_b);for(auto x:s.classification_masks)append(b,x);for(auto x:s.normal_thresholds)append(b,x);return b;
}
void context(const Case&c,Input&in,sq::Scene&s){in.context.spatial.scene=&s;in.context.spatial.area_enable_mask=c.area_mask;in.context.manager=pm::ManagerView{&in.manager,pm::Unknown{}};in.context.null_reference_template=c.templ;
 if(!c.reference.known)in.context.reference=pr::Unknown{};else if(!c.reference.raw)in.context.reference=pr::Absent{};else{check(c.points[0].known&&c.points[2].known,"reference XZ known");in.context.reference=pr::Points{std::bit_cast<float>(c.points[0].raw),std::bit_cast<float>(c.points[2].raw),0,0,c.points[1].optional(),{}};}}

void query(const Query&q,const sq::HeightResult&h,const cr::Resource&r){++query_count;check(h.height_bits==q.height&&h.status==(q.classification&255)&&h.query.classification==q.classification,"original height/status");check(bool(h.query.hit)==bool(q.classification)&&bool(h.attribute)==bool(q.classification),"original hit/attribute");hits+=bool(h.query.hit);if(h.query.hit){const auto&hit=*h.query.hit;const auto&id=hit.identity;check(hit.resource.sha256()==r.sha256(),"hit resource identity");check(id.instance==word(q.carrier,8)&&id.group==word(q.carrier,12)&&id.pair==word(q.carrier,16)&&id.face==word(q.carrier,20),"hit identity");for(unsigned i=0;i<4;++i){check(hit.replacement.plane[i]==word(q.carrier,0x60+4*i),"hit plane");check(hit.replacement.position[i]==word(q.carrier,0x70+4*i),"hit position");check(hit.replacement.opposed_direction[i]==word(q.carrier,0x80+4*i),"hit direction");}check(hit.replacement.t_bits==word(q.carrier,0x90),"hit distance");const auto&a=*h.attribute;check(a.identity==id&&a.resource.sha256()==r.sha256(),"attribute identity");for(unsigned i=0;i<6;++i)check(a.bytes0_5[i]==q.attribute[i],"attribute byte");for(unsigned i=0;i<3;++i){check(a.words2_4_0[i]==word(q.attribute,8+4*i),"attribute word");check(a.normal_bits[i]==word(q.attribute,24+4*i),"attribute raw normal");}check(a.word24==word(q.attribute,36)&&!a.opaque28&&!a.opaque2c,"attribute known/opaque");}
 check(h.query.effects.face_calls.size()==q.faces.size(),"original face count");for(std::size_t i=0;i<q.faces.size();++i){const auto&a=h.query.effects.face_calls[i];const auto&e=q.faces[i];check(a.instance==e[0]&&a.group==e[1]&&a.pair==e[2]&&a.face==e[3],"original ordered faces");}
 check(h.query.grid_updates.size()==(q.updated?1U:0U),"original grid update count");if(q.updated){++grid_count;const auto&u=h.query.grid_updates[0];check(u.slot==0&&u.state.resource.sha256()==r.sha256()&&u.state.group==0,"grid owner");check(u.state.counter==q.counter&&u.state.depth==q.depth&&u.state.pair_marks.size()==q.marks.size(),"grid metadata");for(std::size_t i=0;i<q.marks.size();++i)check(u.state.pair_marks[i]==q.marks[i],"original grid mark");}}
cu::Output successful(cu::Result r){if(const auto*e=std::get_if<cu::Error>(&r))throw std::runtime_error("native error: "+std::string(e->field));return std::get<cu::Output>(std::move(r));}
void originals_run(const Fixture&f,const std::vector<cr::Resource>&rs){for(const auto&c:f.cases){try{auto in=decode(c.before),expected=decode(c.after);auto s=scene(c,rs[c.source]);context(c,in,s);
 const auto p=in.p;const auto fields=in.f;const auto position=in.position;const auto manager=in.manager;const auto grid=scene_snapshot(s);
 if(c.entry==0xd0ce2c){auto r=cu::radius_contains({0,0,0},0x3f800000,0x40000000,in.context);check(std::holds_alternative<bool>(r)&&std::get<bool>(r)==bool(c.result),"original radius");check(expected.p==p&&expected.f==fields&&expected.position==position,"radius original unchanged");}
 else{auto out=successful(c.entry==0xb6ab74?cu::integrate(in.p,in.f,in.position,in.context):c.entry==0xb3150c?cu::contact(in.p,in.f,in.position,in.context):c.entry==0xb3c244?cu::refresh(in.p,in.f,in.position,in.context):cu::apply(in.p,in.f,in.position,in.context));
 check(out.player==expected.p,"original Player fields");check(out.fields==expected.f,"original shared fields/knowledge");check(out.position==expected.position,"original position fields");std::vector<cu::CallKind>wanted;for(const auto&x:c.calls)if(auto k=mh4u::test_contact_effects::call(x[0]))wanted.push_back(*k);check(out.effects.call_count==wanted.size(),"original helper count");for(std::size_t i=0;i<wanted.size();++i)check(out.effects.calls[i]==wanted[i],"original helper order");calls+=wanted.size();check(bool(out.effects.height)==bool(c.query),"original query presence");if(c.query){check(out.effects.attribute_mask==c.query->mask&&out.effects.wrapper_flags==c.query->flags,"original query masks");query(*c.query,*out.effects.height,rs[c.source]);}published+=out.effects.contact_written;
 }
 check(in.p==p&&in.f==fields&&in.position==position&&in.manager==manager&&scene_snapshot(s)==grid,"all borrowed owners unchanged");++originals;
 }catch(const std::exception&e){throw std::runtime_error("case "+std::to_string(c.index)+" "+c.name+": "+e.what());}}
 for(const auto&r:rs){auto b=r.bytes();check(picosha2::hash256_hex_string(reinterpret_cast<const char*>(b.data()),reinterpret_cast<const char*>(b.data()+b.size()))==r.sha256(),"borrowed SBC unchanged");}
 check(originals==262&&query_count==55&&hits==29&&published==7&&grid_count==50,"original coverage");}
