 x=in;x.context.spatial.area_enable_mask.reset();e=reject(x,cu::contact,cu::ErrorCode::mask,"b43194 flags");
 check(std::get<mh4u::player_spatial_acquisition::Error>(e.cause).field=="area manager+18","flags nested cause");
 x=in;x.context.spatial.scene=nullptr;reject(x,cu::contact,cu::ErrorCode::unknown_field,"spatial scene");
 x=in;x.context.spatial.query_limits.nodes=0;e=reject(x,cu::contact,cu::ErrorCode::query,"2ba230/2bb178");check(std::get<sq::Error>(e.cause).code==sq::ErrorCode::resource_limit,"query budget nested cause");
 x=in;x.p.pw.field6c0=1;x.f.pbw.field01.reset();e=reject(x,cu::apply,cu::ErrorCode::unknown_field,"pbw+1");check(e.phase==cu::Phase::permission,"late permission after contact remains typed");
 x=in;x.f.pbw.field6e8_bits.reset();x.f.pbw.field6f0_bits.reset();auto lazy=successful(cu::contact(x.p,x.f,x.position,x.context));check(lazy.effects.contact_written,"unused previous XZ remain lazy");
 auto overlay=out.effects.height->query.grid_updates;const auto overlay_copy=overlay;
