 check(twice.effects.contact_written&&twice.effects.height->query.grid_updates.size()==1,"sequential overlay hit");
 check(twice.effects.height->query.grid_updates[0].state.counter==out.effects.height->query.grid_updates[0].state.counter.value()+1U,"overlay counter consumed cumulatively");
 check(overlay[0].slot==overlay_copy[0].slot&&overlay[0].state.counter==overlay_copy[0].state.counter&&overlay[0].state.depth==overlay_copy[0].state.depth&&overlay[0].state.pair_marks==overlay_copy[0].state.pair_marks,"borrowed overlay unchanged");
 check(in.p==p&&in.f==fields&&in.position==position&&in.manager==manager&&scene_snapshot(scene0)==snapshot,"query controls preserve owners");
