int main(int argc,char**argv){try{boundaries();if(argc!=1&&argc!=4)throw std::runtime_error("arguments");if(argc==4){auto raw=load(argv[1],16U*1024*1024);check(picosha2::hash256_hex_string(raw)==argv[2],"fixture SHA");auto f=parse(raw);std::vector<cr::Resource>sources;for(const auto&s:f.sources){auto r=cr::Resource::load(std::string(argv[3])+"/"+s.path,s.sha);check(std::holds_alternative<cr::Resource>(r),"source load");sources.push_back(std::get<cr::Resource>(std::move(r)));}originals_run(f,sources);query_boundaries(f,sources);}std::cout<<"{\"checks\":"<<checks<<",\"cases\":"<<originals<<",\"calls\":"<<calls<<",\"queries\":"<<query_count<<",\"hits\":"<<hits<<",\"published\":"<<published<<",\"grid_updates\":"<<grid_count<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
